            else:
                self.handle_http(head)
        except Exception as e:
            sys.stderr.write("handler error: %s\n" % e)
            try:
                self.request.sendall(b"HTTP/1.1 502 Bad Gateway\r\nContent-Length: 0\r\nConnection: close\r\n\r\n")
            except Exception:
                pass
        finally:
            try:
                self.request.close()
            except Exception:
                pass

    def handle_connect(self, head):
        reqline = head.split(b"\r\n")[0]
        hostport = reqline.split(b" ")[1].decode()
        host = hostport.rsplit(":", 1)[0]
        port = int(hostport.rsplit(":", 1)[1]) if ":" in hostport else 443
        if is_cluster_local(host):
            up = socket.create_connection((host, port), timeout=30)
            self.request.sendall(b"HTTP/1.1 200 Connection Established\r\n\r\n")
        else:
            up = socket.create_connection((UPSTREAM_HOST, UPSTREAM_PORT), timeout=30)
            connect_req = (
                "CONNECT %s:%d HTTP/1.1\r\nHost: %s:%d\r\nProxy-Authorization: Basic %s\r\nProxy-Connection: keep-alive\r\n\r\n"
                % (host, port, host, port, BASIC)
            )
            up.sendall(connect_req.encode())
            resp = b""
            while b"\r\n\r\n" not in resp:
                chunk = up.recv(4096)
